import os, base64, shutil
HERE = os.path.dirname(os.path.abspath(__file__))

sc = ''
with open(os.path.join(HERE,'src','well_scaling.py'),'wb') as f: f.write(base64.b64decode(sc))
print('  wrote src/well_scaling.py')

rn = ''
with open(os.path.join(HERE,'run_scaling.py'),'wb') as f: f.write(base64.b64decode(rn))
print('  wrote run_scaling.py')

pl = ''
vp = os.path.join(HERE,'src','well_visualizer.py')
with open(vp,'r',encoding='utf-8') as f: vs = f.read()
if 'plot_scaling_results' not in vs:
    with open(vp,'ab') as f: f.write(base64.b64decode(pl))
    print('  appended plot_scaling_results to well_visualizer.py')
else: print('  already present')

for d in ['src/__pycache__','__pycache__']:
    full=os.path.join(HERE,d)
    if os.path.exists(full): shutil.rmtree(full)
print('Done! Run: python run_scaling.py')